package com.fixmyphone.device
import android.content.*; import com.facebook.react.bridge.*
class AppLauncherModule(private val ctx:ReactApplicationContext):ReactContextBaseJavaModule(ctx){override fun getName()="AppLauncher";@ReactMethod fun open(name:String,p:Promise){val pm=ctx.packageManager;val apps=pm.queryIntentActivities(Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0);val match=apps.firstOrNull{it.loadLabel(pm).toString().equals(name,true)||it.loadLabel(pm).toString().contains(name,true)};if(match==null){p.resolve(result("failed","app_not_found"));return};val i=pm.getLaunchIntentForPackage(match.activityInfo.packageName);ctx.startActivity(i!!.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));p.resolve(result("executed",null))};private fun result(s:String,r:String?)=Arguments.createMap().apply{putString("status",s);r?.let{putString("reason",it)}}}
